/** Seconds since the Unix epoch, UTC. */
export type Timestamp = number;

/** The user's relation to the channel. `followed` = follow without subscribing. */
export type Relation = "subscribed" | "followed" | "ex" | "ignored";

export type ChannelSource = "extension" | "link" | "demo" | "theme" | "list" | "mytube";

/** First origin of a video; never changes after the first `VideoStore.upsert`. */
export type VideoOrigin = "rss" | "search" | "hn" | "list";

export type VideoState = "new" | "seen" | "later" | "archived" | "watched";

export type Reaction = "up" | "down";

/** Interface label only; the engine always evaluates `include − exclude → filters`. */
export type TabKind = "category" | "channels" | "theme" | "mixed";

export type FeedMode = "fresh" | "classics" | "long";

export type WhyVia = "folder" | "tag" | "channel" | "theme" | "hn" | "list";

export type ThemeStatus = "searching" | "preview" | "saved" | "error";

export type ThemeVerdict = "keep" | "cut" | "user_down";

export type ThemeItemSource = "search" | "classics" | "rss";

export type SeedAction = "follow" | "subscribe" | "ignore";

export type SuggestionKind = "organize" | "cleanup" | "seed";

export type SuggestionStatus = "pending" | "accepted" | "rejected" | "superseded";

export type CleanupGroup = "stale" | "ignored" | "off_profile" | "manual";

export type CandidateStatus = "pending" | "approved" | "dismissed";

export type QueueAction = "unsubscribe" | "resubscribe";

export type QueueStatus = "approved" | "running" | "done" | "failed" | "undone";

/** The only human approval paths. There is no REST approval route. */
export type ApprovedVia = "desktop_rpc" | "ask_choice";

export type JobKind = "organize" | "cleanup_scan" | "theme" | "list_import" | "digest";

export type JobStatus = "queued" | "running" | "done" | "error";

/** Theme steps with numbers (`ProgressStep.name`): `create` goes through `expand` → `search` → `curate` → `preview`; `refresh` starts with `seeds`. */
export type ThemeStep = "expand" | "search" | "curate" | "preview" | "seeds";

export type SearchOrder = "relevance" | "date";

export type SearchJobStatus = "pending" | "claimed" | "done" | "expired" | "failed";

export type SearchVia = "extension" | "host" | "none";

/** `complete` = the extension scrolled the whole list; only then do absent ones become `ex`. */
export type SyncSignal = "complete" | "partial";

export type Actor = "user" | "hermes" | "extension" | "routine";

/** AI tasks; the prompt + JSON Schema of each one live in `core/prompts.py`. */
export type AiTask = "organize" | "cleanup_reasons" | "theme_expand" | "theme_curate" | "list_extract" | "digest";

/** Batch operations of the Manage screen (`ChannelService.batch`). Batch "Unsubscribe" is **not** a `BatchOp`: the route calls `Cleanup.propose`, which only creates cleanup candidates (never a queue item). */
export type BatchOp = "favorite" | "unfavorite" | "mute" | "unmute" | "move" | "tag" | "untag" | "follow" | "ignore";

export type ReadScopeKind = "channel" | "folder" | "all" | "tab";

export type RoutineKind = "no_agent" | "agent";

/** History actions (`changes.action`). The owner of each undo is in `CHANGE_ACTION_OWNER`. */
export type ChangeAction = "channel_add" | "channel_update" | "channel_relation" | "channel_move" | "channel_tags" | "channel_batch" | "folder_create" | "folder_update" | "folder_delete" | "folder_reorder" | "tag_create" | "tag_update" | "tag_delete" | "tab_create" | "tab_update" | "tab_delete" | "tab_reorder" | "video_state" | "mark_read" | "organize_accept" | "cleanup_approve" | "cleanup_resubscribe" | "theme_save" | "demo_load" | "data_import";

