/** `GET /ai/status`: is there an AI model? Only reads the Hermes configuration and the last call's outcome (no network), so the screens can warn before the click. `available` = the gateway's Hermes will try to call; a bad credential shows up on the first call (`llm_unavailable`) and then here as `provider_unavailable` for a while. */
export interface AiStatus {
  available: boolean;
  /** Model that will answer (the plugin task's, otherwise the main one); `None` = unknown. */
  model: string | null;
  /** `None` when `available`; otherwise one of `AI_STATUS_REASONS`. */
  reason: string | null;
  /** Provider of that model (the plugin task's pinned one, otherwise the main one); absent = unknown or `auto`. */
  provider?: string | null;
}

