/** RPC methods (`host.request(rpcMethod(name), params)`); answer = Envelope<data>. */
export interface RpcMethods {
  /** Cancels an AI job (cooperative; idempotent) · plugin/rpc/jobs.py · direct */
  "job.cancel": {
    kind: "direct";
    params: JobCancelParams;
    data: JobCancelResult;
    jobResult: never;
    errors: "invalid";
  };
  /** Generates folder/tag suggestions with AI (nothing is applied) · plugin/rpc/organize.py · job */
  "organize.run": {
    kind: "job";
    params: OrganizeRunParams;
    data: JobAccepted;
    jobResult: OrganizeResult;
    errors: "llm_unavailable" | "busy" | "invalid";
  };
  /** Applies suggestions (block or channel) through the services, in one history group · plugin/rpc/organize.py · direct */
  "organize.accept": {
    kind: "direct";
    params: OrganizeAcceptParams;
    data: AcceptReport;
    jobResult: never;
    errors: "not_found" | "invalid" | "conflict";
  };
  /** Rejects suggestions (block or channel) · plugin/rpc/organize.py · direct */
  "organize.reject": {
    kind: "direct";
    params: OrganizeRejectParams;
    data: RejectResult;
    jobResult: never;
    errors: "invalid";
  };
  /** Builds the cleanup (rules + AI reasons); approves nothing and changes no channel · plugin/rpc/cleanup.py · job */
  "cleanup.scan": {
    kind: "job";
    params: EmptyParams;
    data: JobAccepted;
    jobResult: CleanupScan;
    errors: "busy";
  };
  /** Human approval of an unsubscribe → queue items (approved_via = desktop_rpc) · plugin/rpc/cleanup.py · direct */
  "cleanup.approve": {
    kind: "direct";
    params: ChannelIdsParams;
    data: QueueItems;
    jobResult: never;
    errors: "approval_refused" | "not_found" | "conflict" | "invalid";
  };
  /** Resubscribe (Former subscriptions) → a resubscribe item in the same queue · plugin/rpc/cleanup.py · direct */
  "cleanup.resubscribe": {
    kind: "direct";
    params: ChannelIdsParams;
    data: QueueItems;
    jobResult: never;
    errors: "approval_refused" | "not_found" | "conflict" | "invalid";
  };
  /** Creates a theme tab by search (expands, batch search, curates) up to the preview · plugin/rpc/themes.py · job */
  "theme.create": {
    kind: "job";
    params: ThemeCreateParams;
    data: JobAccepted;
    jobResult: ThemePreview;
    errors: "llm_unavailable" | "busy" | "invalid";
  };
  /** Saves the theme as a tab (and an optional folder); applies follow/subscribe/ignore to the seeds · plugin/rpc/themes.py · direct */
  "theme.save": {
    kind: "direct";
    params: ThemeSaveParams;
    data: ThemeSaved;
    jobResult: never;
    errors: "not_found" | "invalid" | "conflict";
  };
  /** New search + curation of a theme (kept videos stay) · plugin/rpc/themes.py · job */
  "theme.refresh": {
    kind: "job";
    params: ThemeIdParams;
    data: JobAccepted;
    jobResult: ThemePreview;
    errors: "not_found" | "invalid" | "llm_unavailable" | "busy";
  };
  /** Downloads the page, extracts channels with AI, resolves them and stores the preview · plugin/rpc/lists.py · job */
  "lists.import": {
    kind: "job";
    params: ListImportParams;
    data: JobAccepted;
    jobResult: ListPreview;
    errors: "conflict" | "invalid" | "llm_unavailable" | "busy";
  };
  /** Turns the preview into a tab (and follows the resolved channels) · plugin/rpc/lists.py · direct */
  "lists.to_tab": {
    kind: "direct";
    params: ListToTabParams;
    data: Tab;
    jobResult: never;
    errors: "not_found" | "conflict" | "invalid";
  };
  /** Pairing code; turns on the extension server in the gateway if nobody did · plugin/rpc/pair.py · direct */
  "pair.start": {
    kind: "direct";
    params: EmptyParams;
    data: PairStartResponse;
    jobResult: never;
    errors: "ext_endpoint_down";
  };
}

export type RpcMethodName = keyof RpcMethods;

/** Events (`ctx.onEvent(eventType(name), …)`): payload by short name. */
export interface TubeEvents {
  /** End of an RSS cycle (`Refresher.refresh_all`) */
  "refresh.done": RefreshReport;
  /** The unsubscribe queue changed (approval, extension result, undo) */
  "queue.changed": QueueChangedPayload;
  /** Cleanup built */
  "cleanup.scanned": CleanupScannedPayload;
  /** "Organize with Hermes" suggestions ready */
  "organize.done": JobEventPayload;
  /** Step of a theme creation/refresh (expand, search, curate, preview) */
  "theme.progress": ThemeProgressPayload;
  /** Theme preview ready (or error) */
  "theme.ready": JobEventPayload;
  /** Imported list preview ready (or error) */
  "lists.ready": JobEventPayload;
}

export type TubeEventName = keyof TubeEvents;

/** Every error code, in x-error-codes order. */
export const ERROR_CODES = ["not_found", "conflict", "invalid", "unauthorized", "undo_refused", "approval_refused", "timeout", "busy", "llm_unavailable", "llm_invalid", "youtube_error", "http_error", "origin_forbidden", "origin_required", "origin_mismatch", "host_forbidden", "plugin_disabled", "no_active_code", "invalid_code", "expired", "used", "locked", "ext_endpoint_down", "internal"] as const;

/** Envelope of every REST, ext and RPC answer. */
export type Envelope<T> = { ok: true; data: T } | { ok: false; error: ApiError };
